import unittest
import literal_setting as app

class Behavior(unittest.TestCase):
    def test_raw_content(self):
        for s,want in [("''",''),("'C:\\new\\ship'",'C:\\new\\ship'),("'  quay  '",'  quay  '),("'a\\t#b'",'a\\t#b'),("'海港'",'海港'),("'a\tb'",'a\tb')]:
            self.assertEqual(app.read_literal(s),want)


if __name__ == "__main__":
    unittest.main()
